 const objectName=(f:Feature)=>({car:'Coche',bus:'Autobús',truck:'Camión',motorcycle:'Moto',bike:'Bicicleta',ped:'Peatón',cone:'Cono',sign:'Señal',free:'Dibujo',line:'Línea',arrow:'Flecha',zone:'Zona',text:'Texto'} as Record<string,string>)[f.kind]||'Elemento';
 const selectObject=(id:string)=>{setSelected(id||null);setTool('select');setRouteMode(false);setPlaying(false);setPlayProgress(0)};
 const routeOwner=features.find(f=>f.id===selected&&MOVABLE_KINDS.includes(f.kind));
 const routePoints=routeOwner?.route?.map(p=>project(p))||[];
 const rendered=useMemo(()=>features.map(f=>({f,pts:screenPoints(f)})),[features,view,mapReady,layer,bearing,pitch,vectorZoom,vectorReady]);
 return <div className={"app-shell "+(fullscreenMap?"map-fullscreen":"")}>
 <header className="top"><div className="brand"><div className="brand-icon"><MapPinned size={21}/></div><div><b>PIZARRA VIAL</b><small>MAPA Y DIBUJO</small></div></div><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&searchPlace()} placeholder="Buscar calle, localidad o dirección"/><button onClick={searchPlace} disabled={busy}>{busy?'…':'Buscar'}</button></div><input className="project-name" value={name} onChange={e=>setName(e.target.value)} aria-label="Nombre del escenario"/><button className="topbtn save" onClick={save}><Save size={16}/> Guardar</button><div className="file-menu-wrap"><button className="topbtn" onClick={()=>setShowFileMenu(v=>!v)} aria-expanded={showFileMenu}><Menu size={16}/> Opciones</button>{showFileMenu&&<div className="file-dropdown"><button onClick={()=>{setActiveTemplate(null);setLayer('esquema');setRoadEditor(true);setShowFileMenu(false)}}><Pencil size={16}/> Crear carretera</button><button onClick={()=>{setShowTemplates(true);setShowFileMenu(false)}}><LayoutTemplate size={16}/> Plantillas</button><button onClick={()=>{setShowProjects(true);setShowFileMenu(false)}}><FolderOpen size={16}/> Mis mapas</button><button onClick={()=>{exportSvg();setShowFileMenu(false)}}><Download size={16}/> Exportar</button></div>}</div><button className="mobile-menu" onClick={()=>setMobileTools(v=>!v)}><Menu/></button></header>
 <main className="work-area"><aside className={'tools '+(mobileTools?'tools-open':'')}><div className="panel-tabs"><button className={activePanel==='draw'?'active':''} onClick={()=>setActivePanel('draw')}>Dibujar</button><button className={activePanel==='objects'?'active':''} onClick={()=>setActivePanel('objects')}>Objetos</button><button className={activePanel==='actions'?'active':''} onClick={()=>setActivePanel('actions')}>Editar</button></div><div className="panel-content">{activePanel==='draw'&&<><div className="tools-title">HERRAMIENTAS</div>{tools.map(([id,label,Icon])=><button key={id} className={'tool '+(tool===id?'active':'')} onClick={()=>{setTool(id);setMobileTools(false)}} title={label}><Icon size={19}/><span>{label}</span></button>)}<div className="palette-title">COLORES</div><div className="palette">{COLORS.map(c=><button key={c} aria-label={'Color '+c} className={color===c?'color active-color':'color'} style={{background:c}} onClick={()=>setColor(c)}/>)}</div></>}{activePanel==='objects'&&<><div className="object-picker"><label htmlFor="object-select">OBJETOS DEL ESCENARIO ({features.length})</label><select id="object-select" value={selected||''} onChange={e=>selectObject(e.target.value)}><option value="">Selecciona un objeto…</option>{features.map((f,i)=><option key={f.id} value={f.id}>{i+1}. {objectName(f)}</option>)}</select>{selected&&<div className="object-picker-actions"><button onClick={duplicateSelected}>Duplicar</button><button onClick={deleteSelected}>Eliminar</button></div>}{routeOwner&&<div className="object-picker-actions"><button onClick={startRoute}>Crear recorrido</button>{routeOwner.route&&routeOwner.route.length>1&&<button onClick={()=>{setRouteMode(false);setPlayProgress(0);setPlaying(true)}}>▶ Simular</button>}</div>}</div></>}{activePanel==='actions'&&<><div className="palette-title">COLORES</div><div className="palette">{COLORS.map(c=><button key={c} aria-label={'Color '+c} className={color===c?'color active-color':'color'} style={{background:c}} onClick={()=>setColor(c)}/>)}</div><div className="tool-separator"/><button className="tool" disabled={!routeOwner} onClick={startRoute}>Trazar recorrido</button><button className="tool" disabled={!routeOwner?.route||routeOwner.route.length<2} onClick={()=>{setRouteMode(false);setPlayProgress(0);setPlaying(true)}}>▶ Simular</button><button className="tool" onClick={()=>setPlaying(false)}>⏸ Pausar</button><button className="tool" disabled={!routeOwner?.route} onClick={clearRoute}>Borrar recorrido</button><button className="tool" disabled={!selected} onClick={()=>resizeSelected(.8)}>− Tamaño</button><button className="tool" disabled={!selected} onClick={()=>resizeSelected(1.25)}>+ Tamaño</button><button className="tool" disabled={!selected} onClick={()=>rotateSelected(-15)}>↶ Girar objeto</button><button className="tool" disabled={!selected} onClick={()=>rotateSelected(15)}>↷ Girar objeto</button><button className="tool" disabled={!selected} onClick={duplicateSelected}>Duplicar seleccionado</button><button className="tool" onClick={redo} disabled={!redoStack.length}>Rehacer</button><button className="tool" onClick={undo}><Undo2 size={18}/><span>Deshacer</span></button><button className="tool" onClick={removeSelected} disabled={!selected}><Trash2 size={18}/><span>Eliminar selección</span></button><button className="tool" onClick={()=>{setFeatures([]);setSelected(null);setActiveTemplate(null);setCustomRoads([])}}><X size={18}/><span>Limpiar todo</span></button><div className="hint">Elige una herramienta y dibuja directamente sobre el mapa. Con el cursor puedes mover y explorar.</div></>}</div></aside>
 <section className="map-panel"><div className="map-toolbar"><button className="fullscreen-toggle" onClick={()=>{setFullscreenMap(v=>!v);setMobileTools(false);setTimeout(()=>{map.current?.invalidateSize();vectorMap.current?.resize()},100)}}>{fullscreenMap?"Salir de pantalla completa":"Pantalla completa"}</button><div className="layers"><button className={layer==='calles'?'chosen':''} onClick={()=>{setActiveTemplate(null);setLayer('calles')}}><MapIcon size={16}/> Calles</button><button className={layer==='satelite'?'chosen':''} onClick={()=>{setActiveTemplate(null);setLayer('satelite')}}><Satellite size={16}/> Satélite</button><button className={layer==='esquema'?'chosen':''} onClick={()=>setLayer('esquema')}><Layers size={16}/> Limpio</button><button className={layer==='3d'?'chosen':''} onClick={()=>{setActiveTemplate(null);setLayer('3d');setVectorZoom(Math.max(18,map.current?.getZoom()||18))}}><Layers size={16}/> Mapa limpio</button></div><div className="map-actions"><button title="Acercar a la carretera" onClick={()=>{if(layer==='3d'){const z=Math.min(22,(vectorMap.current?.getZoom()||view.zoom)+1);setVectorZoom(z);vectorMap.current?.zoomTo(z);}else map.current?.zoomIn(1)}}><Plus size={17}/></button><button title="Alejar" onClick={()=>{if(layer==='3d'){const z=Math.max(1,(vectorMap.current?.getZoom()||view.zoom)-1);setVectorZoom(z);vectorMap.current?.zoomTo(z);}else map.current?.zoomOut(1)}}><Minus size={17}/></button>{layer==='3d'&&<><button title="Girar mapa a la izquierda" onClick={()=>setBearing(v=>(v-30+360)%360)}>↶</button><button title="Girar mapa a la derecha" onClick={()=>setBearing(v=>(v+30)%360)}>↷</button><button title="Cambiar perspectiva" onClick={()=>setPitch(v=>v===0?45:0)}>{pitch===0?'3D':'2D'}</button><button title="Orientar al norte" onClick={()=>{setBearing(0);setPitch(0)}}>N</button></>}<button title={locating?"Buscando tu ubicación…":"Centrar en mi ubicación"} aria-label="Centrar en mi ubicación" disabled={locating} onClick={locateMe}><LocateFixed size={17}/>{locating?" Localizando…":""}</button></div></div><div className="map-host" ref={host}><div ref={vectorHost} className={"vector-map "+(layer==='3d'?"vector-map-visible":"")+(tool==="select"?" vector-interactive":"")}/>{layer==='esquema'&&<div className="active-scene-board">{activeTemplate&&<ScenePreview id={activeTemplate}/>}<svg viewBox="0 0 1000 650" preserveAspectRatio="xMidYMid meet" style={{position:'absolute',inset:0,width:'100%',height:'100%'}}><RoadSurface roads={customRoads}/></svg></div>}<svg ref={svg} className={'drawing-overlay '+(tool==='select'?'':'drawing-mode')} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>{rendered.map(({f,pts})=>{if(!pts.length)return null;const selectedClass=selected===f.id?' selected-feature':'';if(['free','line','arrow','zone','road','marking'].includes(f.kind)){const points=pts.map(p=>p.x+','+p.y).join(' ');return <g key={f.id} className={selectedClass} onClick={()=>{if(tool==='select')setSelected(f.id);if(tool==='eraser'){setFeatures(v=>v.filter(x=>x.id!==f.id));setRedoStack([])}}}>{f.kind==='road'?<polyline points={points} fill="none" stroke="#263746" strokeWidth="3.2" strokeLinecap="square" strokeLinejoin="miter"/>:f.kind==='marking'?<polyline points={points} fill="none" stroke="#66717d" strokeWidth="1.8" strokeDasharray="8 5" strokeLinecap="butt" strokeLinejoin="miter"/>:<polyline points={points} fill={f.kind==='zone'?f.color+'22':'none'} stroke={f.color} strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" markerEnd={f.kind==='arrow'?'url(#arrowhead)':'none'}/>}</g>}return <g key={f.id} className={selectedClass} onPointerDown={e=>{if(routeMode||tool!=='select'||f.kind==='text'||f.kind==='template-label')return;e.stopPropagation();e.preventDefault();setSelected(f.id);draggingObject.current=f.id;dragPointer.current=e.pointerId;map.current?.dragging.disable();e.currentTarget.setPointerCapture(e.pointerId)}} onClick={()=>{if(tool==='select')setSelected(f.id);if(tool==='eraser'){setFeatures(v=>v.filter(x=>x.id!==f.id));setRedoStack([])}}} transform={(()=>{const pos=playing||playProgress>0?routePosition(f.route||[],playProgress):null;const xy=pos?project(pos.point):pts[0];return 'translate('+xy.x+' '+xy.y+') rotate('+(pos?pos.angle:f.rotation||0)+') scale('+(f.scale||1)+')'})()}>{f.kind==='text'||f.kind==='template-label'?<text fontSize="16" fontWeight="700" fill={f.color} textAnchor="middle">{f.text}</text>:<TopViewSymbol kind={f.kind} color={f.color}/>}</g>})}{routePoints.length>1&&<polyline points={routePoints.map(p=>p.x+','+p.y).join(' ')} fill="none" stroke="#16a34a" strokeWidth="4" strokeDasharray="8 5" pointerEvents="none"/>}<defs><marker id="arrowhead" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0 0 L0 6 L9 3 z" fill={color}/></marker></defs></svg></div>{fullscreenMap&&<div className="fullscreen-draw-tools"><select aria-label="Seleccionar objeto" value={selected||''} onChange={e=>selectObject(e.target.value)}><option value="">Objetos ({features.length})</option>{features.map((f,i)=><option key={f.id} value={f.id}>{i+1}. {objectName(f)}</option>)}</select><button className={tool==="select"?"chosen":""} onClick={()=>setTool("select")}>Mover</button><button className={tool==="free"?"chosen":""} onClick={()=>setTool("free")}>Lápiz</button><button className={tool==="arrow"?"chosen":""} onClick={()=>setTool("arrow")}>Flecha</button><button className={tool==="line"?"chosen":""} onClick={()=>setTool("line")}>Línea</button><button disabled={!routeOwner} onClick={startRoute}>Ruta</button><button disabled={!routeOwner?.route||routeOwner.route.length<2} onClick={()=>{setRouteMode(false);setPlayProgress(0);setPlaying(true)}}>▶</button><button onClick={()=>setPlaying(false)}>⏸</button><button disabled={!selected} onClick={()=>resizeSelected(.8)}>− Tamaño</button><button disabled={!selected} onClick={()=>resizeSelected(1.25)}>+ Tamaño</button><button disabled={!selected} onClick={()=>rotateSelected(-15)}>↶ Objeto</button><button disabled={!selected} onClick={()=>rotateSelected(15)}>↷ Objeto</button><button onClick={undo}>Deshacer</button><button disabled={!redoStack.length} onClick={redo}>Rehacer</button><button disabled={!selected} onClick={duplicateSelected}>Duplicar</button><button className={tool==="eraser"?"chosen":""} onClick={()=>setTool("eraser")}>Borrar</button><button onClick={save}>Guardar</button><button onClick={()=>setFullscreenMap(false)}>Salir</button></div>}{routeMode&&<div className="route-guide"><b>Diseñar recorrido</b><span>1. Toca el mapa para marcar el camino del vehículo. 2. Añade varios puntos y termina. 3. Reproduce o avanza manualmente con la barra.</span><div><button onClick={()=>{setFeatures(v=>v.map(f=>f.id===selected?{...f,route:f.route?.slice(0,-1)}:f))}}>↶ Último punto</button><button onClick={()=>{setRouteMode(false);setRouteHelp(false)}}>Terminar ({routeOwner?.route?.length||0} puntos)</button></div></div>}{routeOwner?.route&&routeOwner.route.length>1&&!routeMode&&<div className="simulation-controls"><span className="simulation-title">Recorrido · arrastra para avanzar</span><button onClick={()=>{setPlaying(false);setPlayProgress(0)}}>↺</button><input type="range" min="0" max="100" value={Math.round(playProgress*100)} onChange={e=>{setPlaying(false);setPlayProgress(Number(e.target.value)/100)}}/><button onClick={()=>setPlaying(v=>!v)}>{playing?"Pausar":"Reproducir"}</button><select value={playSpeed} onChange={e=>setPlaySpeed(Number(e.target.value))}><option value="0.5">0,5×</option><option value="1">1×</option><option value="2">2×</option></select></div>}<div className="map-status"><span><i/> Mapa interactivo · {layer==='satelite'?'Imagen satélite Esri':layer==='esquema'?'Escenario vial ilustrado':layer==='3d'?'Mapa vectorial limpio · vista cenital':'OpenStreetMap'}</span><span>{features.length} elementos dibujados · Zoom {view.zoom}</span></div></section></main>
 {showTemplates&&<div className="modal-backdrop" onClick={()=>setShowTemplates(false)}><section className="templates-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><b>Biblioteca de escenarios</b><small>{SCENE_GROUPS.reduce((n,g)=>n+g.ids.length,0)} plantillas seleccionadas · vista esquemática limpia</small></div><button onClick={()=>setShowTemplates(false)}><X/></button></div><input className="template-search" value={templateSearch} onChange={e=>setTemplateSearch(e.target.value)} placeholder="Buscar glorieta, cruce, aparcamiento…"/><div className="scene-group-grid">{SCENE_GROUPS.filter(g=>g.ids.some(id=>TEMPLATES.some(t=>t.id===id&&(t.name+' '+t.description).toLowerCase().includes(templateSearch.toLowerCase())))).map(g=><button key={g.name} className={'scene-group-card '+(expandedGroup===g.name?'scene-group-active':'')} onClick={()=>setExpandedGroup(expandedGroup===g.name?null:g.name)}><div className="scene-group-picture"><ScenePreview id={g.ids[0]}/></div><div className="scene-group-copy"><div><b>{g.name}</b><small>{g.subtitle}</small></div><span className="scene-count">{g.ids.length}</span></div></button>)}</div>{expandedGroup&&<div className="scene-expanded"><div className="scene-expanded-head"><b>{expandedGroup} · Elige una plantilla</b><button onClick={()=>setExpandedGroup(null)}><X size={18}/></button></div><div className="scene-subgrid">{SCENE_GROUPS.find(g=>g.name===expandedGroup)?.ids.map(id=>{const t=TEMPLATES.find(t=>t.id===id);return t?<button key={id} className="scene-option" onClick={()=>applyTemplate(t)}><div className="scene-option-picture"><ScenePreview id={id}/></div><b>{t.name}</b><small>{t.description}</small></button>:null})}</div></div>}<p className="template-footnote">Al elegir una plantilla, se coloca en el mapa en modo limpio. Puedes añadir coches, señales, flechas y dibujos encima. Se sustituye el dibujo actual; guarda antes si quieres conservarlo.</p></section></div>}
 {roadEditor&&<RoadEditor roads={customRoads} selected={selectedRoad} onSelect={setSelectedRoad} onChange={setCustomRoads} onClose={()=>setRoadEditor(false)}/>} {notice&&<button className="notice" onClick={()=>setNotice('')}>{notice}　×</button>}
 {showProjects&&<div className="modal-backdrop" onClick={()=>setShowProjects(false)}><section className="projects-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><b>Mis mapas y escenarios</b><small>Guardados en este dispositivo</small></div><button onClick={()=>setShowProjects(false)}><X/></button></div>{projects.length===0?<div className="empty-projects"><FolderOpen size={36}/><b>Aún no has guardado ningún mapa</b><span>Cuando guardes un escenario aparecerá aquí.</span></div>:projects.map(p=><div className="project-row" key={p.id}><div><b>{p.name}</b><small>{p.updated} · {p.features.length} elementos</small></div><button onClick={()=>open(p)}>Abrir</button><button className="delete-project" onClick={()=>{const next=projects.filter(x=>x.id!==p.id);setProjects(next);localStorage.setItem(KEY,JSON.stringify(next))}}><Trash2 size={16}/></button></div>)}<button className="backup" onClick={()=>{const b=new Blob([JSON.stringify(projects,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='mis-mapas-pizarra-vial.json';a.click();URL.revokeObjectURL(a.href)}}><Download size={16}/> Copia de seguridad de mis mapas</button></section></div>}
 <footer className="bottom-note">Pizarra Vial · Herramienta de apoyo para la enseñanza práctica de la conducción <span>Los mapas y dibujos se guardan localmente en este dispositivo.</span></footer>
 </div>;
